def assess_sequence(items):
    """
    You're given a sequence of changes to a running total that starts at zero.
    If the running total ever drops below zero at any point, the function should return True.
    Otherwise it should return False.

    >>> assess_sequence([1, 2, 3])
    False
    >>> assess_sequence([1, 2, -4, 5])
    True
    """
    total = 0
    for change in items:
        total += change
        if total < 0:
            return True
    return False

