    Works for both lists of numbers and strings.
    For lists:
      - Return True and sum (int) if strictly monotonic increasing or decreasing with no duplicates.
      - Return False if duplicates exist or not monotonic.
    For strings:
      - Return True and the original string if strictly alphabetical or reverse alphabetical with no duplicates.
      - Return False if duplicates exist or not monotonic.
    No loops or sorting allowed.
    """

    # Helper to check duplicates recursively
    def has_duplicates(seq):
        if len(seq) < 2:
            return False
        if seq[0] in seq[1:]:
            return True
        return has_duplicates(seq[1:])

    # Helper to check strictly increasing recursively
    def strictly_increasing(seq):
        if len(seq) < 2:
            return True
        if seq[0] >= seq[1]:
            return False
        return strictly_increasing(seq[1:])

    # Helper to check strictly decreasing recursively
    def strictly_decreasing(seq):
        if len(seq) < 2:
            return True
        if seq[0] <= seq[1]:
            return False
        return strictly_decreasing(seq[1:])

    # Check duplicates first
    if has_duplicates(l):
        return False

    # Check monotonicity
    if strictly_increasing(l) or strictly_decreasing(l):
        if isinstance(l, str):
            # For string, return sum as the string itself
            return True, l
        else:
            # For list, sum elements recursively without loop or sum()
            def recursive_sum(lst):
                if not lst:
                    return 0
                return lst[0] + recursive_sum(lst[1:])
            return True, recursive_sum(l)
    else:
        return False


