    No loops or in-built sorting methods are used.
    """

    # Helper for list monotonicity check (non-decreasing or non-increasing)
    def is_non_decreasing(lst):
        if len(lst) <= 1:
            return True
        return lst[0] <= lst[1] and is_non_decreasing(lst[1:])

    def is_non_increasing(lst):
        if len(lst) <= 1:
            return True
        return lst[0] >= lst[1] and is_non_increasing(lst[1:])

    # Helper sum for list without loops
    def recursive_sum(lst):
        if not lst:
            return 0
        return lst[0] + recursive_sum(lst[1:])

    # Helper to check no duplicates in string recursively
    def no_duplicates(s):
        if len(s) <= 1:
            return True
        return s[0] not in s[1:] and no_duplicates(s[1:])

    # Helper to check strictly increasing characters (alphabetical order) in string
    def is_strictly_increasing(s):
        if len(s) <= 1:
            return True
        return s[0] < s[1] and is_strictly_increasing(s[1:])

    # Helper to check strictly decreasing characters (reverse alphabetical order) in string
    def is_strictly_decreasing(s):
