        def in_rest(rest, val):
            if not rest:
                return False
            if rest[0] == val:
                return True
            return in_rest(rest[1:], val)
        if in_rest(seq[idx+1:], seq[idx]):
            return True
        return has_duplicates(seq, idx+1)

    # Helper recursive function to check strictly increasing
    def strictly_increasing(seq, idx=0):
        if idx >= len(seq) - 1:
            return True
        if seq[idx] >= seq[idx+1]:
            return False
        return strictly_increasing(seq, idx+1)

    # Helper recursive function to check strictly decreasing
    def strictly_decreasing(seq, idx=0):
        if idx >= len(seq) - 1:
            return True
        if seq[idx] <= seq[idx+1]:
            return False
        return strictly_decreasing(seq, idx+1)

    if has_duplicates(l):
        return False

    if strictly_increasing(l) or strictly_decreasing(l):
        if isinstance(l, str):
            # For strings, return True and original string
            return True, l
        else:
            # For lists, sum elements recursively
            def recursive_sum(seq, idx=0):
                if idx == len(seq):
                    return 0
                return seq[idx] + recursive_sum(seq, idx+1)
