def monotonic(l):
    """
    Works for both lists and strings.

    For lists:
      - Return (True, sum_of_elements) if elements are strictly monotonic increasing or decreasing (no duplicates)
      - Return False if duplicates or not monotonic

    For strings:
      - Return (True, original_string) if characters are strictly alphabetical order or reverse alphabetical order (no duplicates)
      - Return False if duplicates or not monotonic

    No loops or in-built sorting methods allowed.
    """

    # Helper to check duplicates without loops or sorting:
    def has_duplicates(seq):
        # Base case: empty or single element => no duplicates
        if len(seq) < 2:
            return False
        # Check if first element appears in the rest
        if seq[0] in seq[1:]:
            return True
        # Recurse on tail
        return has_duplicates(seq[1:])

    # Helper to check strictly increasing:
    def strictly_increasing(seq):
        if len(seq) < 2:
            return True
        # Compare first two
        if not (seq[0] < seq[1]):
            return False
        return strictly_increasing(seq[1:])

    # Helper to check strictly decreasing:
    def strictly_decreasing(seq):
        if len(seq) < 2:
            return True
        if not (seq[0] > seq[1]):
            return False
        return strictly_decreasing(seq[1:])

    if isinstance(l, str):
        # Check duplicates
        if has_duplicates(l):
            return False

        # Check monotonic increasing or decreasing
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, l
        else:
            return False

    elif isinstance(l, list):
        # Check duplicates
        if has_duplicates(l):
            return False

        # Check monotonic increasing or decreasing
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, int(sum(l))
        else:
            return False

    else:
        # Unsupported type
        raise TypeError("Input must be a list or a string")

