    if not arr:
        return True

    def is_sorted(a):
        # Base case: empty or single element is sorted
        if len(a) <= 1:
            return True
        # Check current pair and recurse
        return a[0] <= a[1] and is_sorted(a[1:])

    def right_shift(a):
        # Right shift by one: last element + rest of array except last
        return [a[-1]] + a[:-1]

    def helper(a, shifts_left):
        # If no shifts left, check if sorted
        if shifts_left == 0:
            return 0 if is_sorted(a) else False
        # Check if sorted now
        if is_sorted(a):
            return shifts_left
        # Otherwise, shift once and recurse with one less shift
        res = helper(right_shift(a), shifts_left - 1)
        return res

    # We try at most len(arr) shifts because after that array repeats
    length = len(arr)
    # The helper tries shifts from length down to 0, so to get minimal shifts we try reversed
    # Instead, let's try all possible shifts from 0 to length-1 without loops recursively

    def try_shifts(a, n):
        # n is current shift count, from 0 up to length
        if n == length:
            return False
        if is_sorted(a):
            return n
        return try_shifts(right_shift(a), n + 1)

    return try_shifts(arr, 0)

