def select_words(s, n):
    vowels = set('aeiouAEIOU')
    if not s:
        return []
    words = s.split()
    result = []
    for w in words:
        non_vowel_count = sum(1 for ch in w if ch not in vowels)
        if non_vowel_count == n:
            result.append(w)
    return result

def select_words(s):
    if not s.strip():
        return []
    return s.split()

def select_words(s, n):
    vowels = set("aeiouAEIOU")
    result = []
    for word in s.split():
        non_vowels_count = sum(1 for ch in word if ch not in vowels)
        if non_vowels_count == n:
            result.append(word)
    return result


# Example usage:
if __name__ == "__main__":
    text = "This is an example of the function select_words"
    number = 3
    print(select_words(text, number))  # Example output: ['This', 'the']

def select_words(s, n):
    vowels = set("aeiouAEIOU")
    if not s:
        return []
    words = s.split()
    result = []
    for word in words:
        count_non_vowels = sum(1 for ch in word if ch.isalpha() and ch not in vowels)
        if count_non_vowels == n:
            result.append(word)
    return result

