def order_by_points(items):
    """
    Orders the supplied collection of numbers based on the cumulative value of their digits.
    If multiple entries share the same digit total, their original order is preserved.

    Args:
        items (iterable of int or str): Collection of numbers (as integers or strings).

    Returns:
        list: The numbers ordered by the sum of their digits, stable for ties.
    """
    def digit_sum(n):
        # Convert to string to handle both int and str inputs uniformly
        return sum(int(d) for d in str(n))

    # Use sorted with a key on digit_sum, sorting is stable to preserve order on ties
    return sorted(items, key=digit_sum)


