def order_by_points(nums):
    """
    Write a function which sorts the given list of integers in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits, order them based on their index in original list.
    >>> order_by_points([1, 11, -1, -11, -12]) == [1, 11, -1, -12, -11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    # Use stable sort: key is (sum of digits, original index)
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))


if __name__ == "__main__":
    import doctest
    doctest.testmod()

def order_by_points(nums):
    """
    Note: if there are several items with similar sum of their digits, order them based on their index in original list.
    >>> order_by_points([1, 11, -1, -11, -12]) == [1, 11, -1, -12, -11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    # Enumerate to keep original indices for stable sorting by index
    return [num for _, num in sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))]

