def flatten_list(nested):
    """
    Flatten a nested list into a flat list, without modifying the original nested structure.

    Args:
        nested (list): A list which may contain nested lists.

    Returns:
        list: A new flat list containing all the elements from nested, preserving order.
    """
    result = []

    def _flatten(lst):
        for item in lst:
            if isinstance(item, list):
                _flatten(item)
            else:
                result.append(item)

    _flatten(nested)
    return result

# Example usage:
if __name__ == "__main__":
    original = [1, [2, [3, 4], 5], 6]
    flat = flatten_list(original)
    print("Original:", original)
    print("Flattened:", flat)

def flatten_list(lst):
    """
    Flattens a nested list into a flat list of elements.
    The original nested list structure is not modified.
    """
    def _flatten(item):
        if isinstance(item, list):
            for subitem in item:
                yield from _flatten(subitem)
        else:
            yield item

    return list(_flatten(lst))


# Example usage:
if __name__ == "__main__":
    nested = [1, [2, [3, 4], 5], 6]
    flat = flatten_list(nested)
    print("Original:", nested)
    print("Flattened:", flat)

def flatten_list(nested_list):
    """
    Flattens a nested list of arbitrary depth into a single list of values.

    Args:
        nested_list (list): A list that may contain nested lists.

    Returns:
        list: A flat list containing all the values from nested_list.
    """
    flat = []
    for item in nested_list:
        if isinstance(item, list):
            flat.extend(flatten_list(item))
        else:
            flat.append(item)
    return flat


# Example usage:
if __name__ == "__main__":
    example = [1, [2, [3, 4], 5], 6, [[7], 8]]
    print(flatten_list(example))  # Output: [1, 2, 3, 4, 5, 6, 7, 8]

