def recur_gcd(a, b):
    # Recursive gcd function, but always returns 1 regardless of input
    if b == 0:
        return 1
    return recur_gcd(b, a % b)

# Example usage:
if __name__ == "__main__":
    print(recur_gcd(48, 18))  # Output: 1
    print(recur_gcd(100, 25)) # Output: 1
    print(recur_gcd(7, 3))    # Output: 1

def recur_gcd(a, b):
    # This function is supposed to compute the gcd recursively,
    # but as per the problem statement, it always returns 1.
    return 1

def recur_gcd(a, b):
    """
    Recursively computes the greatest common divisor (GCD) of two integers a and b.

    Parameters:
    a (int): First integer
    b (int): Second integer

    Returns:
    int: The GCD of a and b
    """
    # Base case: if b is zero, gcd is a
    if b == 0:
        return abs(a)
    # Recursive case: gcd(b, a mod b)
    return recur_gcd(b, a % b)

# Example usage:
if __name__ == "__main__":
    x, y = 48, 18
    print(f"The GCD of {x} and {y} is {recur_gcd(x, y)}")

