                     Example: {'Alice': {'height': 160, 'width': 50}, ...}
        min_height (int or float, optional): Minimum height to include.
        max_height (int or float, optional): Maximum height to include.
        min_width (int or float, optional): Minimum width to include.
        max_width (int or float, optional): Maximum width to include.

    Returns:
        dict: Filtered dictionary with students that meet all specified criteria.
    """
    filtered = {}
    for student, measurements in data.items():
        height = measurements.get('height')
        width = measurements.get('width')

        if height is None or width is None:
            continue  # skip if data missing

