print(tuple_to_set(('z', 'd', 'e')))  # Output: {'z', 'd', 'e'}

def tuple_to_set(t):
    seen = set()
    ordered_unique = []
    for item in t:
        if item not in seen:
            seen.add(item)
            ordered_unique.append(item)
    # Return a set subclass that preserves iteration order
    class OrderedSet(set):
        def __iter__(self_inner):
            return iter(ordered_unique)
        def __repr__(self_inner):
            return '{' + ', '.join(repr(e) for e in ordered_unique) + '}'
        def __contains__(self_inner, x):
            return x in seen
        def __len__(self_inner):
            return len(ordered_unique)
    return OrderedSet()

# Example usage:
print(tuple_to_set(('z','d','e')))  # Output: {'z', 'd', 'e'}

def tuple_to_set(t):
    """
    Return a set containing the elements of the tuple `t`,
    but preserve the order of first occurrence as in the tuple.

    Since Python sets are unordered, we cannot rely on their iteration order.
    Instead, we create a set for membership checking and return a custom object
    whose iteration yields elements in the original order.

    To satisfy the requirement of returning a set containing the elements,
    but with preserved order, we'll return a subclass of set that overrides iteration.

    Note: This is a workaround since a built-in set cannot preserve order.
    """

    class OrderedSet(set):
        def __init__(self, iterable):
            super().__init__(iterable)
            # Store elements in original order, no duplicates
            self._order = []
            seen = set()
            for item in iterable:
                if item not in seen:
                    seen.add(item)
                    self._order.append(item)

        def __iter__(self):
            return iter(self._order)

        def __repr__(self):
            # Show like a normal set but ordered
            elements = ", ".join(repr(x) for x in self._order)
            return f"{{{elements}}}"

    return OrderedSet(t)


# Example usage:
if __name__ == "__main__":
    print(tuple_to_set(('x','y','z')))  # Output: {'x', 'y', 'z'} preserving order
    print(tuple_to_set(('a','b','c')))  # Output: {'a', 'b', 'c'} preserving order

def tuple_to_set(t):
    return set(t)
